const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const amazonTaskCopy={
 'search-results':{title:'Поисковая выдача',hint:'Поисковая фраза',example:'water bottle',prompt:'Хочу сравнить предложения в поисковой выдаче Amazon.'},
 search:{title:'Найти товары',hint:'Что искать в Amazon',example:'insulated water bottle',prompt:'Хочу сравнить термобутылки на Amazon: цены и рейтинги.'},
 products:{title:'Карточки товаров',hint:'Ссылка на товар Amazon',example:'https://www.amazon.com/dp/B0CRMZHDG8',prompt:'Хочу получить цену и характеристики этого товара.'},
 reviews:{title:'Отзывы',hint:'Ссылка на товар Amazon',example:'https://www.amazon.com/dp/B094NC89P9',prompt:'Хочу собрать отзывы о товаре для разбора жалоб покупателей.'},
 sellers:{title:'Продавец',hint:'Ссылка на страницу продавца Amazon',example:'https://www.amazon.com/sp?seller=…',prompt:'Нужна публичная информация о продавце.'},
 bestsellers:{title:'Бестселлеры',hint:'Ссылка на раздел Best Sellers',example:'https://www.amazon.com/Best-Sellers/zgbs',prompt:'Хочу посмотреть бестселлеры в выбранной категории.'},
 category:{title:'Категория',hint:'Ссылка на категорию Amazon',example:'https://www.amazon.com/…',prompt:'Хочу сравнить товары из этой категории.'},
 brand:{title:'Бренд',hint:'Ссылка на страницу бренда Amazon',example:'https://www.amazon.com/stores/…',prompt:'Хочу изучить ассортимент бренда.'},
 'seller-products':{title:'Ассортимент продавца',hint:'Ссылка на продавца Amazon',example:'https://www.amazon.com/sp?seller=…',prompt:'Хочу получить список товаров этого продавца.'},
 upc:{title:'По штрихкоду',hint:'Штрихкод UPC',example:'012345678905',prompt:'Найти товар по штрихкоду.'}
};
export function ecommercePage(){return `<section class="commerce-intro"><div class="overline">КАТАЛОГ / E-COMMERCE</div><h1>E-commerce</h1><p>Данные о товарах, ценах, отзывах и продавцах. Выберите площадку — все её инструменты собраны в одном продукте.</p></section><article class="amazon-feature"><div class="amazon-mark" aria-hidden="true">a<span>⌣</span></div><div><div class="overline">ПЕРВЫЙ ПРОДУКТ РАЗДЕЛА</div><h2>Amazon</h2><p>Ищите товары, сравнивайте цены, собирайте отзывы и изучайте продавцов. Выберите задачу и задайте запрос внутри Affsiwen.</p><div class="amazon-tags"><span>Товары</span><span>Отзывы</span><span>Продавцы</span><span>Бестселлеры</span><span>Категории и бренды</span></div><a class="primary" href="#product/amazon">Открыть Amazon →</a></div></article><section class="commerce-note"><h2>Одна площадка — один продукт</h2><p>Поиск, карточки, отзывы и данные продавцов доступны из одного рабочего пространства. Не нужно выбирать между дублирующими наборами данных. Сейчас первым собираем Amazon; другие площадки появятся после подключения и проверки.</p></section>`;}
export function amazonHome(){return `<section class="commerce-intro"><div class="overline">AFFSIWEN / КАТАЛОГ ПРОДУКТОВ</div><h1>Данные нужной площадки.<br><em>В одном продукте.</em></h1><p>Выберите раздел и площадку, опишите задачу и получите нужную выгрузку внутри Affsiwen. Начинаем с Amazon: товары, цены, отзывы и продавцы.</p></section><section class="commerce-department"><div><div class="overline">РАЗДЕЛ 01</div><h2>E-commerce</h2><p>Изучайте ассортимент, предложения и обратную связь покупателей.</p><a href="#e-commerce" class="secondary">Все продукты раздела →</a></div><article class="amazon-feature"><div class="amazon-mark" aria-hidden="true">a<span>⌣</span></div><div><h2>Amazon</h2><p>Найти товары · собрать отзывы · изучить продавца · посмотреть бестселлеры.</p><a class="primary" href="#product/amazon">Открыть Amazon →</a><small>Запрос и выдача в вашем рабочем пространстве</small></div></article></section><section class="commerce-note"><h2>Как это работает</h2><ol class="journey-steps"><li><span class="step-no">01</span><h3>Выберите площадку</h3><p>Каждый продукт объединяет инструменты одной площадки.</p></li><li><span class="step-no">02</span><h3>Задайте запрос</h3><p>Выберите задачу, рынок и объём. Добавьте фразу или ссылку.</p></li><li><span class="step-no">03</span><h3>Проверьте параметры</h3><p>Перед запуском видно, что собираем и какой результат ожидается.</p></li><li><span class="step-no">04</span><h3>Получите данные</h3><p>Результат в Affsiwen и выгрузка CSV. Статус реального запуска указан в продукте.</p></li></ol></section>`;}
export function amazonPage({connection=null,draft={},plan=null,result=null,error='',pending=false}={}){
 const task=draft.task||'search',copy=amazonTaskCopy[task]||amazonTaskCopy.search;
 const tasks=connection?.tasks||Object.entries(amazonTaskCopy).map(([id,v])=>({id,title:v.title,available:false}));
 return `<section class="amazon-heading"><a class="quiet-link" href="#e-commerce">E-commerce /</a><div class="amazon-heading-row"><div class="amazon-mark" aria-hidden="true">a<span>⌣</span></div><div><h1>Amazon</h1><p>Товары, цены, отзывы и продавцы — в одном рабочем пространстве.</p></div></div><div class="amazon-state"><span class="pill ${connection?.connected?'green':'amber'}">${connection?.connected?'Источник подключён':'Проверяем доступность'}</span><span>Параметры проверяются по доступным операциям. Реальные сборы пока не включены.</span></div></section><div class="amazon-workspace"><aside class="amazon-task-list"><h2>Что хотите сделать?</h2>${tasks.map(t=>`<button type="button" data-action="amazon-task" data-value="${esc(t.id)}" aria-pressed="${task===t.id}"><span>${esc(amazonTaskCopy[t.id]?.title||t.title)}</span><small>${connection&&!t.available?'Проверяется':esc(t.description||'')}</small></button>`).join('')}</aside><section class="amazon-conversation"><div class="amazon-message"><span class="amazon-avatar">A</span><div><strong>Amazon · Affsiwen</strong><p>${task==='search'?'Какие товары ищем? Укажите поисковую фразу, рынок и максимальный объём.':`Задача: ${esc(copy.title.toLowerCase())}. Добавьте нужную ссылку или идентификатор — проверим параметры перед запуском.`}</p></div></div><form id="amazon-request"><label>Что вы хотите узнать?<textarea name="request" required minlength="2" maxlength="2000" placeholder="${esc(copy.prompt)}">${esc(draft.request||'')}</textarea></label><input type="hidden" name="task" value="${esc(task)}"><div class="amazon-example-buttons">${['search','reviews','bestsellers'].map(id=>`<button type="button" class="text-button" data-action="amazon-example" data-value="${id}">${esc(amazonTaskCopy[id].title)}</button>`).join('')}</div><label>${esc(copy.hint)}<input name="value" required minlength="2" maxlength="2000" value="${esc(draft.value||'')}" placeholder="${esc(copy.example)}"></label><div class="form-grid"><label>Рынок Amazon<select name="market">${Object.entries({US:'США · amazon.com',DE:'Германия · amazon.de',GB:'Великобритания · amazon.co.uk',FR:'Франция · amazon.fr',ES:'Испания · amazon.es',IT:'Италия · amazon.it',CA:'Канада · amazon.ca',AU:'Австралия · amazon.com.au'}).map(([id,label])=>`<option value="${id}" ${(draft.market||'US')===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Максимум записей<input name="limit" type="number" min="1" max="100" value="${esc(draft.limit||10)}" required></label></div><details class="amazon-options"><summary>Уточнить доставку</summary><label>Почтовый индекс (необязательно)<input name="zipcode" maxlength="20" value="${esc(draft.zipcode||'')}" placeholder="Влияет на цены и доступность, если поддерживается"></label></details><button class="primary full" ${pending?'disabled':''}>${pending?'Проверяем параметры…':'Подготовить запрос →'}</button><p class="fine">Проверка параметров не запускает сбор и не списывает деньги. Текст описывает вашу цель; точные параметры задаются полями ниже. AI-анализ пока не подключён.</p></form>${error?`<div class="amazon-error" role="alert">${esc(error)}</div>`:''}${plan?`<div class="amazon-plan"><span class="overline">ЗАПРОС ПОДГОТОВЛЕН</span><h2>${esc(plan.title)}</h2><dl><dt>Что собираем</dt><dd>${esc(plan.value)}</dd><dt>Рынок и объём</dt><dd>${esc(plan.market)} · до ${plan.limit} записей · один запрос</dd><dt>Ожидаемые поля</dt><dd>${plan.columns.map(esc).join(' · ')}</dd><dt>Стоимость</dt><dd>Будет подтверждена до реального запуска. Сейчас списаний нет.</dd></dl><p>${esc(plan.notice)}</p><button class="secondary full" data-action="amazon-demo">Открыть демо результата</button><p class="fine">Демо содержит вымышленные строки и показывает формат выдачи. Это не данные Amazon.</p></div>`:''}${result?`<section class="amazon-result"><div class="result-toolbar"><h2>Пример результата</h2><span class="pill amber">ДЕМО · ДАННЫЕ ВЫМЫШЛЕНЫ</span></div><div class="sample-table"><table><caption>${esc(result.title)} · ${result.rows.length} демонстрационных строк</caption><thead><tr>${Object.keys(result.rows[0]||{}).map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${result.rows.map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><a class="secondary" href="/api/amazon/export">Скачать демо CSV</a></section>`:''}</section></div><section class="commerce-note"><h2>Что входит в Amazon</h2><p>Карточки и поиск товаров, отзывы, информация о продавцах, бестселлеры, категории, бренды и ассортимент продавца. Обычные и международные операции выбираются на сервере по рынку и задаче. Для отдельных рынков доступность отличается — проверим её до запуска.</p><p>Готовые архивные базы и сбор по новому запросу — разные режимы. Сейчас настраиваем сбор по запросу. Готовые базы, Walmart-сопоставление, история цен и автоматическая аналитика ещё не добавлены.</p></section>`;
}
